#define MAXN 100005

typedef struct {
    double x, y;
} Point;

typedef struct {
    double cx, cy, r;
} Circle;

Point pts[MAXN];
int n;

double dist(Point a, Point b) {
    return sqrt((a.x-b.x)*(a.x-b.x) + (a.y-b.y)*(a.y-b.y));
}

Circle makeCircle1(Point a) {
    Circle c = {a.x, a.y, 0};
    return c;
}

Circle makeCircle2(Point a, Point b) {
    Circle c;
    c.cx = (a.x + b.x) / 2.0;
    c.cy = (a.y + b.y) / 2.0;
    c.r = dist(a, b) / 2.0;
    return c;
}

Circle makeCircle3(Point a, Point b, Point c) {
    double ax = b.x - a.x, ay = b.y - a.y;
    double bx = c.x - a.x, by = c.y - a.y;
    double D = 2.0 * (ax * by - ay * bx);
    if (fabs(D) < 1e-10) {
        // collinear
        double d1 = dist(a, b), d2 = dist(b, c), d3 = dist(a, c);
        if (d1 >= d2 && d1 >= d3) return makeCircle2(a, b);
        if (d2 >= d1 && d2 >= d3) return makeCircle2(b, c);
        return makeCircle2(a, c);
    }
    double ux = (by * (ax*ax + ay*ay) - ay * (bx*bx + by*by)) / D;
    double uy = (ax * (bx*bx + by*by) - bx * (ax*ax + ay*ay)) / D;
    Circle circle;
    circle.cx = a.x + ux;
    circle.cy = a.y + uy;
    circle.r = sqrt(ux*ux + uy*uy);
    return circle;
}

int inCircle(Circle c, Point p) {
    return dist((Point){c.cx, c.cy}, p) <= c.r + 1e-10;
}

Circle welzl(Point *P, int n_p, Point *R, int n_r) {
    if (n_p == 0 || n_r == 3) {
        if (n_r == 0) return makeCircle1(P[0]); // shouldn't happen if n_p==0 and n_r==0
        if (n_r == 1) return makeCircle1(R[0]);
        if (n_r == 2) return makeCircle2(R[0], R[1]);
        return makeCircle3(R[0], R[1], R[2]);
    }
    // pick last point
    Point p = P[n_p - 1];
    Circle d = welzl(P, n_p - 1, R, n_r);
    if (inCircle(d, p)) return d;
    R[n_r] = p;
    return welzl(P, n_p - 1, R, n_r + 1);
}

