#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <float.h>

typedef struct {
    double x, y;
} Point;

double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx*dx + dy*dy;
}

Point circle_from_2(Point a, Point b) {
    Point c;
    c.x = (a.x + b.x) / 2.0;
    c.y = (a.y + b.y) / 2.0;
    return c;
}

Point circle_from_3(Point a, Point b, Point c) {
    double d = 2.0 * (a.x*(b.y - c.y) + b.x*(c.y - a.y) + c.x*(a.y - b.y));
    if (fabs(d) < 1e-12) {
        // degenerate; return midpoint of farthest pair
        double ab = dist2(a,b), ac = dist2(a,c), bc = dist2(b,c);
        if (ab >= ac && ab >= bc) return circle_from_2(a,b);
        if (ac >= ab && ac >= bc) return circle_from_2(a,c);
        return circle_from_2(b,c);
    }
    double ux = ((a.x*a.x + a.y*a.y)*(b.y - c.y) + 
                 (b.x*b.x + b.y*b.y)*(c.y - a.y) + 
                 (c.x*c.x + c.y*c.y)*(a.y - b.y)) / d;
    double uy = ((a.x*a.x + a.y*a.y)*(c.x - b.x) + 
                 (b.x*b.x + b.y*b.y)*(a.x - c.x) + 
                 (c.x*c.x + c.y*c.y)*(b.x - a.x)) / d;
    Point center = {ux, uy};
    return center;
}

void shuffle(Point *p, int n) {
    for (int i = n-1; i > 0; i--) {
        int j = rand() % (i+1);
        Point tmp = p[i];
        p[i] = p[j];
        p[j] = tmp;
    }
}

// Welzl style recursion, but simplified incremental
Point min_circle(Point *p, int n, Point *bound, int b) {
    if (n == 0 || b == 3) {
        if (b == 0) return (Point){0,0};
        if (b == 1) return bound[0];
        if (b == 2) return circle_from_2(bound[0], bound[1]);
        return circle_from_3(bound[0], bound[1], bound[2]);
    }
    Point c = min_circle(p, n-1, bound, b);
    if (dist2(p[n-1], c) <= dist2(c, c) + 1e-12) return c;
    bound[b] = p[n-1];
    return min_circle(p, n-1, bound, b+1);
}

