#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point c;
    double r;
} Circle;

static const double EPS = 1e-12;

double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int inside(Circle c, Point p) {
    return dist(c.c, p) <= c.r + 1e-9;
}

Circle circle_one(Point a) {
    Circle c;
    c.c = a;
    c.r = 0.0;
    return c;
}

Circle circle_two(Point a, Point b) {
    Circle c;
    c.c.x = (a.x + b.x) / 2.0;
    c.c.y = (a.y + b.y) / 2.0;
    c.r = dist(a, b) / 2.0;
    return c;
}

Circle circle_three(Point a, Point b, Point c) {
    Circle res;
    double ax = a.x, ay = a.y;
    double bx = b.x, by = b.y;
    double cx = c.x, cy = c.y;

    double d = 2.0 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by));

    if (fabs(d) < EPS) {
        res.r = -1.0;
        return res;
    }

    double ax2ay2 = ax * ax + ay * ay;
    double bx2by2 = bx * bx + by * by;
    double cx2cy2 = cx * cx + cy * cy;

    res.c.x = (ax2ay2 * (by - cy) + bx2by2 * (cy - ay) + cx2cy2 * (ay - by)) / d;
    res.c.y = (ax2ay2 * (cx - bx) + bx2by2 * (ax - cx) + cx2cy2 * (bx - ax)) / d;
    res.r = dist(res.c, a);
    return res;
}

void shuffle(Point *p, int n) {
    for (int i = n - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        Point tmp = p[i];
        p[i] = p[j];
        p[j] = tmp;
    }
}

Circle minimum_enclosing_circle(Point *p, int n) {
    shuffle(p, n);

    Circle c;
    c.r = -1.0;

    for (int i = 0; i < n; ++i) {
        if (c.r >= 0 && inside(c, p[i])) continue;

        c = circle_one(p[i]);

        for (int j = 0; j < i; ++j) {
            if (inside(c, p[j])) continue;

            c = circle_two(p[i], p[j]);

            for (int k = 0; k < j; ++k) {
                if (inside(c, p[k])) continue;

                Circle cc = circle_three(p[i], p[j], p[k]);
                if (cc.r < 0) {
                    Circle c1 = circle_two(p[i], p[j]);
                    Circle c2 = circle_two(p[i], p[k]);
                    Circle c3 = circle_two(p[j], p[k]);

                    Circle best;
                    best.r = 1e100;

                    int ok1 = 1, ok2 = 1, ok3 = 1;
                    for (int t = 0; t <= i; ++t) {
                        if (!inside(c1, p[t])) ok1 = 0;
                        if (!inside(c2, p[t])) ok2 = 0;
                        if (!inside(c3, p[t])) ok3 = 0;
                    }
                    if (ok1 && c1.r < best.r) best = c1;
                    if (ok2 && c2.r < best.r) best = c2;
                    if (ok3 && c3.r < best.r) best = c3;
                    c = best;
                } else {
                    c = cc;
                }
            }
        }
    }

    return c;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; ++i) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    srand((unsigned)time(NULL));

    Circle ans = minimum_enclosing_circle(p, N);
    printf("%.10f\n", ans.r);

    free(p);
    return 0;
}

