        }

        if (n == 1) {
            System.out.printf("%.6f%n", 0.0);
            return;
        }

        // Minimum enclosing circle using Welzl's algorithm
        double[] px = x.clone();
        double[] py = y.clone();

        // Shuffle to get expected O(n) time
        Random rand = new Random(42);
        for (int i = n - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            double tmp = px[i]; px[i] = px[j]; px[j] = tmp;
            tmp = py[i]; py[i] = py[j]; py[j] = tmp;
        }

        double cx = px[0], cy = py[0], r = 0;

        for (int i = 1; i < n; i++) {
            if (dist(cx, cy, px[i], py[i]) > r + 1e-10) {
                cx = px[i]; cy = py[i]; r = 0;
                for (int j = 0; j < i; j++) {
                    if (dist(cx, cy, px[j], py[j]) > r + 1e-10) {
                        cx = (px[i] + px[j]) / 2;
                        cy = (py[i] + py[j]) / 2;
                        r = dist(cx, cy, px[i], py[i]);
                        for (int k = 0; k < j; k++) {
                            if (dist(cx, cy, px[k], py[k]) > r + 1e-10) {
                                // Circle through three points
                                double[] c = circumcircle(px[i], py[i], px[j], py[j], px[k], py[k]);
                                cx = c[0]; cy = c[1]; r = c[2];
                            }
                        }
                    }
                }
            }
        }

        System.out.printf("%.6f%n", r);
    }

    static double dist(double x1, double y1, double x2, double y2) {
        double dx = x1 - x2, dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }

    static double[] circumcircle(double ax, double ay, double bx, double by, double cx, double cy) {
        double D = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by));
        if (Math.abs(D) < 1e-10) {
            // Collinear points - find the two farthest apart
            double d1 = dist(ax, ay, bx, by);
            double d2 = dist(bx, by, cx, cy);
            double d3 = dist(ax, ay, cx, cy);
            double mx, my, r;
            if (d1 >= d2 && d1 >= d3) {
                mx = (ax + bx) / 2; my = (ay + by) / 2; r = d1 / 2;
            } else if (d2 >= d1 && d2 >= d3) {
                mx = (bx + cx) / 2; my = (by + cy) / 2; r = d2 / 2;
            } else {
                mx = (ax + cx) / 2; my = (ay + cy) / 2; r = d3 / 2;
            }
            return new double[]{mx, my, r};
        }
        double ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / D;
        double uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / D;
        double r = dist(ux, uy, ax, ay);
        return new double[]{ux, uy, r};
    }
}

import java.util.*;

public class MinEnclosingCircle {
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static double dist(Point a, Point b) {
        return Math.sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
    }

    static Point circleFromTwoPoints(Point a, Point b) {
        double cx = (a.x + b.x) / 2;
        double cy = (a.y + b.y) / 2;
        return new Point(cx, cy);
    }

    static Point circleFromThreePoints(Point a, Point b, Point c) {
        double d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
        if (Math.abs(d) < 1e-12) return null; // collinear case
        double ux = ((a.x * a.x + a.y * a.y) * (b.y - c.y) + 
                     (b.x * b.x + b.y * b.y) * (c.y - a.y) + 
                     (c.x * c.x + c.y * c.y) * (a.y - b.y)) / d;
        double uy = ((a.x * a.x + a.y * a.y) * (c.x - b.x) + 
                     (b.x * b.x + b.y * b.y) * (a.x - c.x) + 
                     (c.x * c.x + c.y * c.y) * (b.x - a.x)) / d;
        return new Point(ux, uy);
    }

    static double radius(Point center, List<Point> points) {
        double r = 0;
        for (Point p : points) {
            r = Math.max(r, dist(center, p));
        }
        return r;
    }

    static double welzl(List<Point> points, List<Point> boundary, int n) {
        if (n == 0 || boundary.size() == 3) {
            if (boundary.isEmpty()) return 0;
            if (boundary.size() == 1) return 0;
            if (boundary.size() == 2) {
                Point center = circleFromTwoPoints(boundary.get(0), boundary.get(1));
                return dist(center, boundary.get(0));
            }
            // 3 points
            Point center = circleFromThreePoints(boundary.get(0), boundary.get(1), boundary.get(2));
            if (center == null) {
                // collinear, take the two farthest apart
                double d01 = dist(boundary.get(0), boundary.get(1));
                double d02 = dist(boundary.get(0), boundary.get(2));
                double d12 = dist(boundary.get(1), boundary.get(2));
                if (d01 >= d02 && d01 >= d12) {
                    Point c = circleFromTwoPoints(boundary.get(0), boundary.get(1));
                    return dist(c, boundary.get(0));
                } else if (d02 >= d01 && d02 >= d12) {
                    Point c = circleFromTwoPoints(boundary.get(0), boundary.get(2));
                    return dist(c, boundary.get(0));
                } else {
                    Point c = circleFromTwoPoints(boundary.get(1), boundary.get(2));
                    return dist(c, boundary.get(1));
                }
            }
            return dist(center, boundary.get(0));
        }

        int idx = new Random().nextInt(n);
        Point p = points.get(idx);
        Collections.swap(points, idx, n - 1);

        double r = welzl(points, boundary, n - 1);
        Point center = getCenter(boundary, r);
        if (center != null && dist(center, p) <= r + 1e-12) {
            return r;
        }

        boundary.add(p);
        double res = welzl(points, boundary, n - 1);
        boundary.remove(boundary.size() - 1);
        return res;
    }

    static Point getCenter(List<Point> boundary, double r) {
        if (boundary.isEmpty()) return null;
        if (boundary.size() == 1) return boundary.get(0);
        if (boundary.size() == 2) return circleFromTwoPoints(boundary.get(0), boundary.get(1));
        return circleFromThreePoints(boundary.get(0), boundary.get(1), boundary.get(2));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            double x = sc.nextDouble();
            double y = sc.nextDouble();
            points.add(new Point(x, y));
        }
        sc.close();

        List<Point> boundary = new ArrayList<>();
        double minR = welzl(points, boundary, points.size());
        System.out.printf("%.10f%n", minR);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static class Circle {
        double x, y, r;
        Circle(double x, double y, double r) {
            this.x = x;
            this.y = y;
            this.r = r;
        }

        boolean contains(Point p) {
            double dx = p.x - x;
            double dy = p.y - y;
            return dx * dx + dy * dy <= r * r + 1e-10;
        }
    }

    static double dist(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    static Circle circleFromTwoPoints(Point a, Point b) {
        double cx = (a.x + b.x) / 2.0;
        double cy = (a.y + b.y) / 2.0;
        double r = dist(a, b) / 2.0;
        return new Circle(cx, cy, r);
    }

    static Circle circleFromThreePoints(Point a, Point b, Point c) {
        double ax = a.x, ay = a.y;
        double bx = b.x, by = b.y;
        double cx = c.x, cy = c.y;

        double d = 2.0 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by));
        if (Math.abs(d) < 1e-12) return null;

        double ux = ((ax * ax + ay * ay) * (by - cy)
                   + (bx * bx + by * by) * (cy - ay)
                   + (cx * cx + cy * cy) * (ay - by)) / d;

        double uy = ((ax * ax + ay * ay) * (cx - bx)
                   + (bx * bx + by * by) * (ax - cx)
                   + (cx * cx + cy * cy) * (bx - ax)) / d;

        double r = Math.hypot(ux - ax, uy - ay);
        return new Circle(ux, uy, r);
    }

    static Circle minimumEnclosingCircle(Point[] pts) {
        List<Point> p = new ArrayList<>(Arrays.asList(pts));
        Collections.shuffle(p, new Random());

        Circle c = null;
        for (int i = 0; i < p.size(); i++) {
            if (c != null && c.contains(p.get(i))) continue;
            c = new Circle(p.get(i).x, p.get(i).y, 0.0);
            for (int j = 0; j < i; j++) {
                if (c.contains(p.get(j))) continue;
                c = circleFromTwoPoints(p.get(i), p.get(j));
                for (int k = 0; k < j; k++) {
                    if (c.contains(p.get(k))) continue;
                    Circle cc = circleFromThreePoints(p.get(i), p.get(j), p.get(k));
                    if (cc != null) c = cc;
                }
            }
        }
        return c;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        Point[] pts = new Point[N];
        for (int i = 0; i < N; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            pts[i] = new Point(x, y);
        }

        Circle ans = minimumEnclosingCircle(pts);
        System.out.printf(Locale.US, "%.10f%n", ans.r);
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}
};

double dist2(const Point &a, const Point &b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx*dx + dy*dy;
}

Point circleFromTwo(const Point &a, const Point &b) {
    return Point((a.x + b.x)/2.0, (a.y + b.y)/2.0);
}

Point circleFromThree(const Point &a, const Point &b, const Point &c) {
    double d = 2.0 * (a.x*(b.y - c.y) + b.x*(c.y - a.y) + c.x*(a.y - b.y));
    double ux = ((a.x*a.x + a.y*a.y)*(b.y - c.y) + (b.x*b.x + b.y*b.y)*(c.y - a.y) + (c.x*c.x + c.y*c.y)*(a.y - b.y)) / d;
    double uy = ((a.x*a.x + a.y*a.y)*(c.x - b.x) + (b.x*b.x + b.y*b.y)*(a.x - c.x) + (c.x*c.x + c.y*c.y)*(b.x - a.x)) / d;
    return Point(ux, uy);
}

void welzlHelper(vector<Point> &P, vector<Point> &R, int n, Point &center, double &radius2) {
    if (n == 0 || R.size() == 3) {
        if (R.empty()) {
            center = Point(0,0);
            radius2 = 0;
        } else if (R.size() == 1) {
            center = R[0];
            radius2 = 0;
        } else if (R.size() == 2) {
            center = circleFromTwo(R[0], R[1]);
            radius2 = dist2(center, R[0]);
        } else {
            center = circleFromThree(R[0], R[1], R[2]);
            radius2 = dist2(center, R[0]);
        }
        return;
    }

    int idx = rand() % n;
    Point p = P[idx];
    swap(P[idx], P[n-1]);

    welzlHelper(P, R, n-1, center, radius2);

    if (dist2(p, center) > radius2 + 1e-9) {
        R.push_back(p);
        welzlHelper(P, R, n-1, center, radius2);
        R.pop_back();
    }
}

double minimumEnclosingCircleRadius(vector<Point> &pts) {
