};

struct Circle {
    double x, y, r;
};

double dist(Point a, Point b) {
    return sqrt((a.x-b.x)*(a.x-b.x) + (a.y-b.y)*(a.y-b.y));
}

Circle circleFrom1(Point a) {
    return {a.x, a.y, 0};
}

Circle circleFrom2(Point a, Point b) {
    double cx = (a.x + b.x) / 2.0;
    double cy = (a.y + b.y) / 2.0;
    double r = dist(a, b) / 2.0;
    return {cx, cy, r};
}

Circle circleFrom3(Point a, Point b, Point c) {
    double ax = b.x - a.x, ay = b.y - a.y;
    double bx = c.x - a.x, by = c.y - a.y;
    double D = 2 * (ax * by - ay * bx);
    if (fabs(D) < 1e-10) {
        // Collinear, return circle from the two farthest points
        double d1 = dist(a, b), d2 = dist(b, c), d3 = dist(a, c);
        if (d1 >= d2 && d1 >= d3) return circleFrom2(a, b);
        if (d2 >= d1 && d2 >= d3) return circleFrom2(b, c);
        return circleFrom2(a, c);
    }
    double ux = (by * (ax*ax + ay*ay) - ay * (bx*bx + by*by)) / D;
    double uy = (ax * (bx*bx + by*by) - bx * (ax*ax + ay*ay)) / D;
    Point center = {a.x + ux, a.y + uy};
    return {center.x, center.y, dist(center, a)};
}

bool inCircle(Circle c, Point p) {
    return dist({c.x, c.y}, p) <= c.r + 1e-10;
}

Circle welzl(vector<Point>& P, vector<Point> R, int n) {
    if (n == 0 || R.size() == 3) {
        if (R.size() == 0) return {0, 0, 0};
        if (R.size() == 1) return circleFrom1(R[0]);
        if (R.size() == 2) return circleFrom2(R[0], R[1]);
        return circleFrom3(R[0], R[1], R[2]);
    }

    int idx = rand() % n;
    swap(P[idx], P[n-1]);
    Point p = P[n-1];

    Circle D = welzl(P, R, n-1);

    if (inCircle(D, p)) return D;

    R.push_back(p);
    return welzl(P, R, n-1);
}

