struct Point {
    double x, y;
};

static const double EPS = 1e-12;

double dist(const Point& a, const Point& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

bool inside(const Point& p, const Point& c, double r) {
    return dist(p, c) <= r + 1e-9;
}

pair<Point, double> circleFromTwoPoints(const Point& a, const Point& b) {
    Point c{(a.x + b.x) / 2.0, (a.y + b.y) / 2.0};
    double r = dist(a, b) / 2.0;
    return {c, r};
}

bool circleFromThreePoints(const Point& a, const Point& b, const Point& c, Point& center, double& r) {
    double d = 2.0 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    if (fabs(d) < EPS) return false;

    double a2 = a.x * a.x + a.y * a.y;
    double b2 = b.x * b.x + b.y * b.y;
    double c2 = c.x * c.x + c.y * c.y;

    center.x = (a2 * (b.y - c.y) + b2 * (c.y - a.y) + c2 * (a.y - b.y)) / d;
    center.y = (a2 * (c.x - b.x) + b2 * (a.x - c.x) + c2 * (b.x - a.x)) / d;
    r = dist(center, a);
    return true;
}

