def circle_from_two(p1, p2):
    cx = (p1[0] + p2[0]) / 2.0
    cy = (p1[1] + p2[1]) / 2.0
    r2 = dist2(p1, (cx, cy))
    return (cx, cy, r2)

def circle_from_three(p1, p2, p3):
    ax, ay = p1
    bx, by = p2
    cx, cy = p3
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    if abs(d) < 1e-12:
        return None
    ux = ((ax**2 + ay**2) * (by - cy) + (bx**2 + by**2) * (cy - ay) + (cx**2 + cy**2) * (ay - by)) / d
    uy = ((ax**2 + ay**2) * (cx - bx) + (bx**2 + by**2) * (ax - cx) + (cx**2 + cy**2) * (bx - ax)) / d
    r2 = dist2((ux, uy), p1)
    return (ux, uy, r2)

def welzl(points):
    points = points[:]
    random.shuffle(points)

    def min_circle(pts, boundary):
        if len(pts) == 0 or len(boundary) == 3:
            if len(boundary) == 0:
                return (0.0, 0.0, 0.0)
            elif len(boundary) == 1:
                return (boundary[0][0], boundary[0][1], 0.0)
            elif len(boundary) == 2:
                return circle_from_two(*boundary)
            elif len(boundary) == 3:
                return circle_from_three(*boundary)

        p = pts.pop()
        c = min_circle(pts, boundary)
        if dist2(p, (c[0], c[1])) <= c[2] + 1e-12:
            pts.append(p)
            return c
        boundary.append(p)
        c = min_circle(pts, boundary)
        boundary.pop()
        pts.append(p)
        return c

