import math
import random

EPS = 1e-10

def dist(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return math.hypot(dx, dy)

def is_inside(p, c):
    cx, cy, r = c
    return math.hypot(p[0] - cx, p[1] - cy) <= r + 1e-9

def circle_from_two_points(a, b):
    cx = (a[0] + b[0]) / 2.0
    cy = (a[1] + b[1]) / 2.0
    r = dist(a, b) / 2.0
    return (cx, cy, r)

def circle_from_three_points(a, b, c):
    ax, ay = a
    bx, by = b
    cx, cy = c

    d = 2.0 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    if abs(d) < EPS:
        return None

    ax2ay2 = ax * ax + ay * ay
    bx2by2 = bx * bx + by * by
    cx2cy2 = cx * cx + cy * cy

    ux = (ax2ay2 * (by - cy) + bx2by2 * (cy - ay) + cx2cy2 * (ay - by)) / d
    uy = (ax2ay2 * (cx - bx) + bx2by2 * (ax - cx) + cx2cy2 * (bx - ax)) / d
    r = math.hypot(ux - ax, uy - ay)
    return (ux, uy, r)

def minimum_enclosing_circle(points):
    pts = points[:]
    random.shuffle(pts)

    c = (0.0, 0.0, -1.0)

    for i in range(len(pts)):
        if c[2] >= 0 and is_inside(pts[i], c):
            continue
        c = (pts[i][0], pts[i][1], 0.0)
        for j in range(i):
            if is_inside(pts[j], c):
                continue
            c = circle_from_two_points(pts[i], pts[j])
            for k in range(j):
                if is_inside(pts[k], c):
                    continue
                cc = circle_from_three_points(pts[i], pts[j], pts[k])
                if cc is None:
                    # Collinear: take the circle determined by the farthest pair
                    candidates = [
                        circle_from_two_points(pts[i], pts[j]),
                        circle_from_two_points(pts[i], pts[k]),
                        circle_from_two_points(pts[j], pts[k]),
                    ]
                    best = None
                    for cand in candidates:
                        if is_inside(pts[i], cand) and is_inside(pts[j], cand) and is_inside(pts[k], cand):
                            if best is None or cand[2] < best[2]:
                                best = cand
                    c = best
                else:
                    c = cc
    return c

